const body = $input.first().json.body || {};

const tenant_id = body.tenant_id;
const user_id = body.user_id;
const limit = body.limit || 20;
const offset = body.offset || 0;
const filters = body.filters || {};

// Validation
const errors = [];
if (!tenant_id) errors.push('tenant_id requis');
if (!user_id) errors.push('user_id requis');

// Validate limit
if (limit < 1 || limit > 100) {
  errors.push('limit doit etre entre 1 et 100');
}

// Validate filters
const validResults = ['win', 'loss', 'draw'];
if (filters.result && !validResults.includes(filters.result)) {
  errors.push(`filters.result invalide: ${filters.result}. Valeurs: ${validResults.join(', ')}`);
}

const validSources = ['manual', 'lichess', 'pgn_import'];
if (filters.source && !validSources.includes(filters.source)) {
  errors.push(`filters.source invalide: ${filters.source}. Valeurs: ${validSources.join(', ')}`);
}

if (filters.has_analysis !== undefined && typeof filters.has_analysis !== 'boolean') {
  errors.push('filters.has_analysis doit etre un booleen');
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' }
    }
  };
}

return {
  json: {
    valid: true,
    tenant_id,
    user_id,
    limit,
    offset,
    filters
  }
};

const input = $('Validate Input').first().json;
const response = $input.first().json;

const statusCode = response.statusCode || 200;
const body = response.body || response;

if (statusCode >= 400 || body.success === false) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: body.error?.message || 'Erreur API',
        details: body
      }
    }
  };
}

const data = body.data || body;

return {
  json: {
    success: true,
    games: data.games || [],
    total: data.total || 0,
    limit: data.limit || input.limit,
    offset: data.offset || input.offset
  }
};
